import os
from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os.path import basename
from string import Template

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.utils.emss import get_emss_connection
from ta_logcollector.utils.internal import save_result_data

logger = Logger("LC")
ACTIVE_ALARMS_HEADER = Template("{0}\nACTIVE_ALARMS - ENB_$id\n{0}".format("*" * 30))
ALARM_HISTORY_HEADER = Template("{0}\nALARMS_HISTORY - ENB_$id\n{0}".format("*" * 30))


def start(alarms_history_path, emss_connections_data):
    # type: (str, dict) -> None
    """
    Gets active alarms and clears alarms history so we can trace it later
    :param alarms_history_path:path to file where alarm data should be stored
    :param emss_connections_data: List of dictionaries with host and port for EmsSim
    """
    logger.info("inside {} before start".format(basename(__file__)))
    try:
        for emss, emss_id in get_emss_connection(logger, emss_connections_data, port=4000):
            active_alarms = emss.get_enb_active_alarms(enb_id=emss_id)
            emss.clear_alarm_history(enb_id=emss_id)
            _save_alarms_to_file(active_alarms, "active", alarms_history_path, emss_id)
    except AssertionError as exc:
        logger.exception("Connection to EMSS not possible - {}".format(exc), exc_info=True)
    logger.info("inside {} after start".format(basename(__file__)))


def _save_alarms_to_file(alarms_data, alarms_type, alarms_history_path, emss_id):
    alarms_type = ACTIVE_ALARMS_HEADER if alarms_type == "active" else ALARM_HISTORY_HEADER
    save_result_data(alarms_type.substitute(id=emss_id), alarms_history_path)
    for alarm in alarms_data:
        save_result_data(alarm, alarms_history_path)


def stop(alarms_history_path, emss_connections_data):
    # type: (str, dict) -> None
    """
    Gets alarms history and saves to provided file
    :param alarms_history_path:path to file where alarm data should be stored
    :param emss_connections_data: List of dictionaries with host and port for EmsSim
    """
    logger.info("inside {} before stop".format(basename(__file__)))
    for emss, emss_id in get_emss_connection(logger, emss_connections_data, port=4000):
        history_alarms = emss.get_alarm_history(enb_id=emss_id)
        if history_alarms:
            _save_alarms_to_file(history_alarms, "history", alarms_history_path, emss_id)
    logger.info("inside {} after stop".format(basename(__file__)))


@contextmanager
def alarms(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> None
    """
    Saves active alarms at the start then clears alarms history and saves history at the end.
    This way there is a full history of alarm in given period
    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    alarms_history_path = os.path.join(log_dir, "alarm_history_{}.txt".format(SERVER_HOST))
    emss_connections_data = kwargs.get("bts_info")
    try:
        start(alarms_history_path, emss_connections_data)
        yield
    finally:
        stop(alarms_history_path, emss_connections_data)
